import XCTest
@testable import Flashback

/// Real `state` messages captured from a live local Worker game (Milestone 4,
/// 4 players, Even Split, every effect and power-up on). They prove the iOS
/// models decode what the server actually sends, not just hand-written JSON.
final class LiveServerDecodingTests: XCTestCase {
    private func view(_ json: String) throws -> RoomView {
        try XCTUnwrap(try JSONDecoder().decode(ServerMessage.self, from: Data(json.utf8)).state)
    }

    func testLobbyDecodesSettingsAndBunch() throws {
        let v = try view(Payloads.lobby)
        XCTAssertEqual(v.phase, .lobby)
        XCTAssertEqual(v.bunch.photos, 12)
        XCTAssertEqual(v.bunch.videos, 6)
        XCTAssertNil(v.activeShop)
        XCTAssertEqual(v.me?.items, PlayerItems())
    }

    func testRevealDecodesStreakAndRoundEffects() throws {
        let v = try view(Payloads.reveal)
        XCTAssertEqual(v.phase, .reveal)
        XCTAssertTrue(v.settings.evenSplit)
        XCTAssertEqual(v.bunch.photos, 2)
        XCTAssertEqual(v.bunch.videos, 0)
        let round = try XCTUnwrap(v.round)
        XCTAssertEqual(round.yourEffect?.kind, .blur)
        XCTAssertEqual(round.yourEffect?.strength, .medium)
        XCTAssertEqual(round.yourEffect?.trigger, .wrong)
        XCTAssertEqual(round.yourEffect?.streak, 3)
        XCTAssertEqual(round.effect?.kind, .zoom)
        XCTAssertEqual(round.effect?.scale, 4)
        XCTAssertEqual(round.effect?.spanMs, 10_000)
        XCTAssertEqual(round.eliminated, [])
    }

    func testResultsDecodeOpenShopAndBreakdown() throws {
        let v = try view(Payloads.shop)
        XCTAssertEqual(v.phase, .results)
        let shop = try XCTUnwrap(v.activeShop)
        XCTAssertTrue(shop.open)
        XCTAssertTrue(shop.bought)
        XCTAssertEqual(shop.prices.doubleDown, 250)
        XCTAssertEqual(shop.prices.shield, 200)
        XCTAssertEqual(shop.prices.fiftyFifty, 400)
        XCTAssertEqual(v.resultsBreakSeconds, 12, "a shop break is at least 12 s")
        let rows = try XCTUnwrap(v.lastResult?.rows)
        XCTAssertEqual(rows.count, 4)
        XCTAssertTrue(rows.contains { $0.doubleDown == .won }, "the host's Double Down won this round")
        XCTAssertTrue(rows.contains { $0.earnedFiftyFifty })
        XCTAssertTrue(rows.contains { $0.bonus > 0 }, "sharp eyes bonus")
    }

    func testFinalResultsCloseTheShopAndKeepThePlainBreak() throws {
        let v = try view(Payloads.final)
        XCTAssertEqual(v.lastResult?.index, 8)
        XCTAssertEqual(v.activeShop?.open, false)
        XCTAssertEqual(v.resultsBreakSeconds, v.settings.breakSeconds)
        XCTAssertTrue(try XCTUnwrap(v.lastResult?.rows).contains { $0.fiftyFifty }, "the owner spent (and got back) a 50/50")
        XCTAssertEqual(v.me?.items.shield, 1)
    }

    func testPodiumDecodes() throws {
        let v = try view(Payloads.podium)
        XCTAssertEqual(v.phase, .podium)
        XCTAssertEqual(v.podium.count, 4)
        XCTAssertEqual(v.podium.first?.rank, 1)
    }
}

